/**
 * "Show the math."
 *
 * Every economic number in this tool is derived. This module produces, alongside each
 * number, the formula that made it and the real values substituted in — so when Gabe
 * clicks a deal or creates a tranche he sees exactly what the backend did, and can say
 * "that term is wrong" on the spot instead of trusting a total.
 *
 * A step is: { key, label, formula, substituted, value, source, note }
 *   - formula     the symbolic form, e.g. "Bill of Sale ÷ Bill-of-Sale %"
 *   - substituted the same with real numbers, e.g. "$29,936 ÷ 0.6589"
 *   - source      where the inputs come from — a CRM field, the pricing matrix, an assumption
 *
 * The final value of the trace MUST equal calc.js's priceDeal() — a test asserts it, so
 * the explanation can never drift from the number the tool actually uses.
 */

import { num, taxCreditFor, tagsFor } from './calc.js';

const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const money = (n) => (n == null ? '—' : n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }));
const money2 = (n) => (n == null ? '—' : n.toLocaleString('en-US', { style: 'currency', currency: 'USD' }));
const pct = (n) => (n == null ? '—' : `${(n * 100).toFixed(2)}%`);

/**
 * Trace a single deal's pricing.
 *
 * @param {object} deal
 * @param {object} opts
 * @param {number|null} opts.bosPct  the investor's bill-of-sale % for this deal's rubric
 * @param {number}      opts.financingFee  Gabe's "+ deal financing fee" term (assumption)
 */
export function explainDeal(deal, opts = {}) {
  const bosPct = opts.bosPct ?? null;
  const financingFee = num(opts.financingFee) ?? 0;
  const steps = [];

  const amount = num(deal.Amount) ?? 0;
  const sow = num(deal.Pre_Pay_Pct_of_Statement_of_Work) ?? 0;
  const storedPrePay = num(deal.Pre_Pay_Amount);
  const addl = num(deal.Additional_Pre_Pay) ?? 0;

  // ── Pre-pay ────────────────────────────────────────────────────────────────────────
  let prePay;
  if (storedPrePay !== null) {
    prePay = storedPrePay;
    steps.push({
      key: 'prePay',
      label: 'Pre-pay amount',
      formula: 'CRM formula field',
      substituted: 'Pre_Pay_Amount (server-computed)',
      value: money2(prePay),
      source: 'CRM',
      note: 'CRM maintains this as a formula field; the widget reads it, never writes it.',
    });
  } else {
    prePay = round2(amount * sow + addl);
    steps.push({
      key: 'prePay',
      label: 'Pre-pay amount',
      formula: 'Amount × Pre-pay % of SOW + Additional pre-pay',
      substituted: `${money2(amount)} × ${sow} + ${money2(addl)}`,
      value: money2(prePay),
      source: 'computed',
      note: 'Verified 100/100 on Tranche 77. Additional pre-pay exists only on sample rows.',
    });
  }

  // ── Tax credit (the EC/DC rubric) ────────────────────────────────────────────────────
  const tc = taxCreditFor(deal);
  const chips = tagsFor(deal).map((t) => t.label).join(' + ');
  steps.push({
    key: 'taxCredit',
    label: 'Tax credit tier',
    formula: '30% base + 10% energy community + 10% domestic content',
    substituted: `30% ${tc.ec ? '+ 10% (EC)' : ''} ${tc.dc ? '+ 10% (DC)' : ''}`.trim() + `  →  ${chips}`,
    value: pct(tc.value),
    source: tc.disagrees ? 'assumption' : 'CRM',
    note: tc.disagrees
      ? `CRM stores ${pct(num(deal.Tax_Credit_Percentage))}, which disagrees with the EC/DC rubric — flagged.`
      : 'From the EC/DC flags on the deal.',
  });

  // ── Bill of Sale ─────────────────────────────────────────────────────────────────────
  // Gabe's stated formula: "the prepaid amount, divided by the bill of sale for
  // percentage, plus the deal financing fee." This is what the pricing matrix is FOR.
  let bos = null;
  if (bosPct) {
    const core = round2(prePay / bosPct);
    bos = round2(core + financingFee);
    steps.push({
      key: 'bos',
      label: 'Bill of sale',
      formula: 'Pre-pay ÷ Bill-of-Sale %' + (financingFee ? ' + financing fee' : ''),
      substituted: `${money2(prePay)} ÷ ${bosPct}` + (financingFee ? ` + ${money2(financingFee)}` : ''),
      value: money2(bos),
      source: 'pricing matrix',
      note:
        'Gabe\'s stated formula. The Bill-of-Sale % comes from this investor\'s pricing matrix ' +
        'for the deal\'s (SOW %, tax credit) rubric.' +
        (financingFee ? '' : ' Financing fee assumed $0 — an open question.'),
    });
  } else {
    const storedBos = num(deal.Bill_of_Sale_Amount);
    bos = storedBos;
    steps.push({
      key: 'bos',
      label: 'Bill of sale',
      formula: bosPct === null ? 'no pricing → CRM value' : 'CRM formula field',
      substituted: storedBos !== null ? 'Bill_of_Sale_Amount (server-computed)' : 'unpriced',
      value: money2(storedBos),
      source: 'CRM',
      note: 'This investor has no rate for the deal\'s rubric, so the tool shows CRM\'s own Bill of Sale until a rate is added.',
    });
  }

  // ── Investor contribution ────────────────────────────────────────────────────────────
  const ic = bos == null ? null : round2(bos - prePay);
  steps.push({
    key: 'ic',
    label: 'Investor contribution',
    formula: 'Bill of sale − Pre-pay',
    substituted: `${money2(bos)} − ${money2(prePay)}`,
    value: money2(ic),
    source: 'computed',
    note: 'Verified 100/100 on Tranche 77.',
  });

  // ── ITC ──────────────────────────────────────────────────────────────────────────────
  const itc = bos == null ? null : round2(bos * tc.value);
  steps.push({
    key: 'itc',
    label: 'Estimated ITC',
    formula: 'Bill of sale × Tax credit %',
    substituted: `${money2(bos)} × ${tc.value}`,
    value: money2(itc),
    source: 'computed',
    note: 'Verified 100/100 on Tranche 77.',
  });

  return { steps, prePay, bos, investorContribution: ic, itc, taxCredit: tc.value };
}

/**
 * Trace a tranche roll-up — the "boom, shows everything, shows like a summary in totals".
 * Each line is Σ over the priced deals, plus the weighted percentages and adders.
 */
export function explainTranche(rows, adders = []) {
  const priced = rows.filter((r) => r.calc.priced);
  const n = priced.length;
  const sum = (f) => round2(priced.reduce((s, r) => s + (f(r.calc) || 0), 0));

  const prePay = sum((c) => c.prePay);
  const bos = sum((c) => c.bos);
  const ic = sum((c) => c.investorContribution);
  const itc = sum((c) => c.itc);
  const addersTotal = round2(adders.reduce((s, a) => s + (num(a.amount) ?? 0), 0));

  const wAmt = sum((c) => c.amount);
  const wSow = wAmt ? priced.reduce((s, r) => s + r.calc.sowPct * r.calc.amount, 0) / wAmt : 0;

  const steps = [
    { key: 'count', label: 'Deals', formula: 'count of priced deals', substituted: `${n} priced of ${rows.length} selected`, value: String(n), source: 'computed' },
    { key: 'prePay', label: 'Total pre-pay', formula: 'Σ deal pre-pay', substituted: `sum over ${n} deals`, value: money2(prePay), source: 'computed' },
    { key: 'bos', label: 'Total bill of sale', formula: 'Σ deal bill of sale', substituted: `sum over ${n} deals`, value: money2(bos), source: 'computed' },
    { key: 'ic', label: 'Investor contribution', formula: 'Σ (bill of sale − pre-pay)', substituted: `${money2(bos)} − ${money2(prePay)}`, value: money2(ic), source: 'computed' },
    { key: 'adders', label: 'Total adders', formula: 'Σ adder charges', substituted: adders.map((a) => a.label + ' ' + money(num(a.amount) ?? 0)).join(', ') || 'none', value: money2(addersTotal), source: 'assumption', note: 'Whether adders are tranche-level or per-deal is an open question.' },
    { key: 'icAdders', label: 'IC incl. adders', formula: 'Investor contribution + total adders', substituted: `${money2(ic)} + ${money2(addersTotal)}`, value: money2(round2(ic + addersTotal)), source: 'computed' },
    { key: 'itc', label: 'Estimated ITC', formula: 'Σ deal ITC', substituted: `sum over ${n} deals`, value: money2(itc), source: 'computed' },
    { key: 'wSow', label: 'Weighted pre-pay % SOW', formula: 'Σ(SOW% × amount) ÷ Σ amount', substituted: `amount-weighted over ${n} deals`, value: pct(wSow), source: 'computed', note: 'Amount-weighted, so a small deal cannot swing it.' },
  ];

  return { steps, prePay, bos, investorContribution: ic, itc, adders: addersTotal };
}

/** Trace what create / lock would do to CRM — the actions that are suppressed in sandbox. */
export function explainAction(kind, ctx = {}) {
  if (kind === 'create') {
    return {
      title: 'Create tranche',
      wouldWrite: [
        { op: 'insertRecord', target: 'Tranches (CustomModule8)', detail: `Name = "${ctx.name}", Investor = ${ctx.investorName}, Tranche_Status = "Open"` },
        { op: 'updateRecord ×N', target: 'Deals', detail: `set Tranche = <new id> on ${ctx.dealCount} deals` },
        { op: 'automation.Untitled_Function2', target: 'Tranches', detail: 'stamps the name "<Investor> Tranche <date>" that report filters depend on' },
      ],
      note: 'Suppressed in sandbox — the tranche is created in this browser only.',
    };
  }
  if (kind === 'lock') {
    return {
      title: 'Lock and generate documents',
      wouldWrite: [
        { op: 'automation.finalizeTranche5', target: 'Tranches + Deals', detail: 'sets Avail_for_Purchase = false on every deal, Tranche_Status = "Locked"' },
        { op: 'email', target: '3 recipients', detail: 'Investor Relations notification' },
        { op: 'snapshot', target: 'Tranche_Logs + Deal_Logs', detail: 'point-in-time JSON of the tranche and every deal' },
        { op: 'zoho.sign.createUsingTemplate', target: 'Zoho Sign', detail: 'BOS + A&AA (template 154758000019030075), signer hardcoded "Jeff Hawkinson"' },
      ],
      note: 'Suppressed in sandbox. This is the loud, hard-to-undo path — deliberately not wired.',
    };
  }
  return { title: kind, wouldWrite: [], note: '' };
}
